#[tokio::main]
async fn main() -> anyhow::Result<()> {
    tracing_subscriber::fmt()
        .event_format(tracing_subscriber::fmt::format().without_time().compact())
        .init();

    let signer: PrivateKeySigner =
        "0xac0974bec39a17e36ba4a6b4d238ff944bacb478cbed5efcae784d7bf4f2ff80"
            .parse()
            .unwrap();
    let wallet = EthereumWallet::from(signer);

    let provider = Arc::new(
        ProviderBuilder::new()
            .with_recommended_fillers()
            .wallet(wallet)
            .on_client(
                ClientBuilder::default()
                    .http("http://localhost:8545".parse().unwrap())
                    .boxed(),
            ),
    );

    let executor = plutus_executor::contract::IExecutor::deploy(provider.clone()).await?;

    let target = address!("0x9FCBC372A15E96E85ACF37C84C91DA21dA005398");
    let data = bytes!(
        ""
    );

    let receipt = executor
        .execute(target, data)
        .send()
        .await?
        .get_receipt()
        .await?;

    tracing::info!("{receipt:#?}");

    Ok(())
}
